    public void setUp() {
        rectangleCounter = new RectangleCounter();
    }

    @Test
    @DisplayName("no rows")
    public void testInputWithNoRowsContainsNoRectangles() {
        String[] inputGrid = new String[]{};

        assertThat(rectangleCounter.countRectangles(inputGrid)).isEqualTo(0);
